def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute form.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: The current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """
    # Track the number of links followed
    links_followed = 0
    max_links = 8

    # Convert relative path to absolute
    if not path.startswith('/'):
        if not cwd.startswith('/'):
            return None
        path = cwd + '/' + path if cwd != '/' else '/' + path

    # Split path into components
    components = path.split('/')

    # Start resolution from root
    current = ''

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current == '':
                current = '/'
            elif current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        while current in links:
            links_followed += 1
            if links_followed > max_links:
                return None

            target = links[current]

            # Resolve target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = target
            else:
                # Relative target - relative to the directory containing the link
                link_dir = current.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'

                if link_dir == '/':
                    current = '/' + target
                else:
                    current = link_dir + '/' + target

            # Normalize the current path (handle . and ..)
            parts = current.split('/')
            normalized = []
            for part in parts:
                if part == '' or part == '.':
                    continue
                elif part == '..':
                    if normalized:
                        normalized.pop()
                else:
                    normalized.append(part)

            current = '/' + '/'.join(normalized)

    # Ensure we have at least '/'
    if current == '':
        current = '/'

    # Remove trailing slash unless it's the root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

